package io.knowledgebrain.activity;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;
import io.knowledgebrain.contracts.content.concepts.v1.*;
class NoteConceptActivityTest extends ActivityFixtures {
 static final String TOPIC="content.note-concepts.v1";
 NoteConceptLinkV1 link(){return NoteConceptLinkV1.newBuilder().setLinkId(id().toString()).setConceptId(id().toString()).build();}
 @Test void independentAssociationVersionPinsRevisionBodyVersionAndOrderedStableIds()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_CONCEPTS",id()));var p=NoteConceptsChangedPayloadV1.parseFrom(env.getPayload());var a=link();var b=link();var wire=env.toBuilder().setPayload(p.toBuilder().setConceptVersion(23).setNoteVersion(7).addLinks(b).addLinks(a).build().toByteString()).build().toByteArray();var e=ActivityEvent.decode(TOPIC,wire);assertEquals(23,e.sourceVersion());assertEquals(7,e.noteConcepts().noteVersion());assertEquals(ActivityEvent.id(p.getRevisionId()),e.noteConcepts().revisionId());assertEquals(List.of(new ActivityEvent.Link(ActivityEvent.id(b.getLinkId()),ActivityEvent.id(b.getConceptId())),new ActivityEvent.Link(ActivityEvent.id(a.getLinkId()),ActivityEvent.id(a.getConceptId()))),e.noteConcepts().concepts());assertEquals("노트 개념 연결",e.title());assertEquals("",e.detail());assertNull(e.note());assertNull(e.content());assertTrue(ActivityEvent.target(e));assertEquals("/api/spaces/"+e.spaceId()+"/notes/"+e.aggregateId()+"/concepts",e.targetPath());ActivityEvent.transport(TOPIC,wire,e.aggregateId().toString(),headers(e));}
 @Test void emptyDetachAndRetiredNoteAreDifferentRetainedFacts()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_CONCEPTS",id()));var p=NoteConceptsChangedPayloadV1.parseFrom(env.getPayload());for(String state:List.of("ACTIVE","RETIRED")){var e=ActivityEvent.decode(TOPIC,env.toBuilder().setPayload(p.toBuilder().setNoteState(state).build().toByteString()).build().toByteArray());assertEquals(state,e.state());assertEquals(List.of(),e.noteConcepts().concepts());}}
 @Test void malformedDuplicateOversizedAndRetiredNonemptySnapshotsAreRejected()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_CONCEPTS",id()));var p=NoteConceptsChangedPayloadV1.parseFrom(env.getPayload());var a=link();var many=p.toBuilder();for(int i=0;i<21;i++)many.addLinks(link());for(var bad:List.of(p.toBuilder().setConceptVersion(0),p.toBuilder().setNoteVersion(0),p.toBuilder().setRevisionId("bad"),p.toBuilder().setNoteId(id().toString()),p.toBuilder().setNoteState("MERGED"),p.toBuilder().addLinks(a).addLinks(a),p.toBuilder().addLinks(a).addLinks(a.toBuilder().setLinkId(id().toString())),p.toBuilder().addLinks(a).addLinks(a.toBuilder().setConceptId(id().toString())),p.toBuilder().setNoteState("RETIRED").addLinks(a),many)){assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,env.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}for(var bad:List.of(env.toBuilder().setAggregateType("Note"),env.toBuilder().setEventType("NoteUpdated"),env.toBuilder().setProducer("knowledge-service")))assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,bad.build().toByteArray()));}
 @Test void frozenPayloadHasNoNamesAndLegacyStoredEntriesStillRead(){var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("NOTE"),wire("NOTE",id()));var json=tools.jackson.databind.json.JsonMapper.builder().build();var tree=(tools.jackson.databind.node.ObjectNode)json.valueToTree(e);tree.remove("noteConcepts");assertEquals(e,json.treeToValue(tree,ActivityEvent.class));}
 @Test void associationCursorBindsSpaceAndKind(){var space=id();var e=ActivityEvent.decode(TOPIC,wire("NOTE_CONCEPTS",space));var q=ActivityQuery.parse(space,ActivityQueryTest.params("kind","NOTE_CONCEPTS","timezone","UTC"));var params=ActivityQueryTest.params("kind","NOTE_CONCEPTS","timezone","UTC","before",q.cursor(e));assertEquals(e.eventId(),ActivityQuery.parse(space,params).event());assertThrows(RuntimeException.class,()->ActivityQuery.parse(id(),params));params.put("kind",new String[]{"NOTE"});assertThrows(RuntimeException.class,()->ActivityQuery.parse(space,params));}
}
